# ---------- 闸⑭ 派生账的每条 CI 必须能从档案自己的 gaps 复算 ----------
# ①–⑬ 吃的是"训练路径产出的那批账"（v4f 名下）或"档案文本"（⑫）或"脚本能不能打开"（⑬）；
# 派生账（零训练、读别人的账算出来的 v4i/v4j/v4k/v4l）里那几十条 95% CI **一条都不在任何闸里**：
# 「那条跨列差 −28.1 张 CI [−42.3, −14.0]」这句话的承重是零——数字抄错一位没人出声。
# 派生账里"等价于一条步长"的那一维 = 凡带 `gaps` 的配对块（段内步长／跨列差／跨族差都是两格逐流相减），
# 所以复算单位取"一条 CI 块"而不是"一本账"：一本账里有几条就复算几条。
# 旧版豁免写成规则而不是名单：同一账族里版本号更高的本已入库 ⇒ 老本留盘只对账、不参评，
# 但豁免名单必须打印；而"最新那一本"里只要还有一条 CI 拿不出 gaps 就红 ⇒ 升版这条路拖不得。
# 专属拆红 --ciderived 两处注入各钉一条腿：改一条 CI 的上端 ⇒「复算不平」；抹掉另一条的 gaps ⇒「口径外」。
DERIVED = re.compile(r"compress_report_v4[ijkl][^/\\]*\.json$")
CI_KEYS = ("n_seeds", "mean_gap_imgs", "sd_imgs", "se_imgs", "ci95_imgs",
           "same_sign_seeds", "p_seeds_binomial", "range_imgs", "d4_sigma_hat")
CI_ALIAS = {"residual_imgs": "mean_gap_imgs", "same_sign": "same_sign_seeds",
            "p": "p_seeds_binomial"}


def _base(book):
    return book.split(chr(92))[-1]


def _famv(book):
    stem = _base(book)[: -len(".json")]
    m = re.search(r"_v(\d+)$", stem)
    return (stem[:m.start()] if m else stem, int(m.group(1)) if m else 0)


def _ci_blocks(node, path=""):
    """展开一本账里所有带 ci95_imgs 的块（连它自己的档案内路径一起交出去）。"""
    if isinstance(node, dict):
        if "ci95_imgs" in node:
            yield path, node
        for k, v in node.items():
            yield from _ci_blocks(v, f"{path}/{k}")
    elif isinstance(node, list):
        for i, v in enumerate(node):
            yield from _ci_blocks(v, f"{path}[{i}]")


