if n14 == 0:
    fails.append("闸⑭ 一条派生账 CI 都没读到——不是通过，是没测到（glob 空转或派生账被改名）")
else:
    print(f"  现读 {n14} 条 ci95：可复算 {n14_recalc} 条（逐字段命中）、口径外 {n14_oob} 条")
if MODE == "--ciderived":
    if inj_recalc and not any(f.startswith("闸⑭") and inj_recalc in f and "复算" in f for f in fails):
        fails.append(f"闸⑭（拆红模式 --ciderived）改了 CI 端点却没抓到（{inj_recalc}）⇒ 复算那条腿恒绿")
    if inj_nogap and not any(f.startswith("闸⑭") and inj_nogap in f and "口径外" in f for f in fails):
        fails.append(f"闸⑭（拆红模式 --ciderived）抹掉 gaps 却没抓到（{inj_nogap}）⇒ 『必须有原料』那条腿恒绿")

# ---------- ⑮ 债句指针（第二十八发：把上一发记成"新欠"的那根会漂的指针变成守卫） ----------
# 形状：档案里「<某本账>.json 的 limitations 第 N 条（『引文』…）」——文件名 + 序号 + 引文三件套齐了才算**可核指针**。
# 判据：引文按 `…` 切成片段，每个片段都必须躺在那本账 `limitations[N-1]` 里；不在就红，并把"按内容命中的是第几条"打出来。
# 为什么值得常驻：`limitations` 每一版都在**头部**插一条变更说明 ⇒ 同一句话的序号每升一版 +1
# （现读 v4i 那本：债句在 v1/v2/v3 = 第 2/3/4 条），所以"写死序号"是一根会自己漂走的指针。
# 只写了"第 N 条"却没点名的那类（裸序号引用）不猜目标，只数出来报分母——猜目标等于把判别器建在假设上。
PTR_FORM = re.compile(r"(compress_report_[A-Za-z0-9_]+\.json)\s*的\s*limitations\s*第\s*(\d+)\s*条[^。；]{0,4}『(.+?)』")
PTR_BARE = re.compile(r"limitations[^。；]{0,14}第\s*\d+\s*条")
NEWEST = {}
for _b in sorted(arch_all):
    _f, _v = _famv(_b)
    if _f not in NEWEST or _v > NEWEST[_f][0]:
        NEWEST[_f] = (_v, _b)
# 参评口径（第廿九发，与闸⑭ 同一条规矩）：**指针的出处**只取每族最高版，旧版留盘豁免。
# 为什么这一条必须由代码持有而不是留在散文里：v4j 那句"转述冒充引用"在 v2 里已经改成逐字了，
# 可 v1 还在盘上（留盘对账是板块规矩），全册扫描就让那一桶永远降不回 0 ⇒ 付了 46 次训练换不来一格变绿，
# 而且下一次升版会把"已还的债"重新记成"在册缺陷"。**目标那一侧仍按全册查**：指针写的是哪本就叫哪本，
# 指到已被取代的旧版正是"过期指针"这一桶的原料，把它从扫描面里删掉等于把桶底凿穿。
_p_top = {}
for _b in sorted(arch_all):
    _f, _v = _famv(_b)
    _p_top[_f] = max(_v, _p_top.get(_f, -1))
P_LATEST = {b for b in arch_all if _famv(b)[1] == _p_top[_famv(b)[0]]}
P_OLD = sorted(set(arch_all) - P_LATEST)


def _ptr_tag(book, path, tgt, n):
    """一条指针的身份证。守卫的红句与 --limitptr 的各腿共用这一个构造：
    拆红腿要靠它认出『哪几条红是我刚注入那一条』，两处各写一遍格式就会静默对不上。"""
    return f"{_base(book)}{path} → {_base(tgt)} 第 {n} 条"


def _ptr_scan(books, src=None):
    """纯函数：抽**参评那批账**里的可核指针 → 逐条按内容核。

    `src` 是出处的扫描面（默认全给）；调用方传 `P_LATEST` 就是"每族最高版参评、旧版豁免"。
    目标一律在 `books`（全册）里查，理由见上面那段。

    返回 (指针清单, 裸序号引用条数, 红清单, 过期指针清单, 引文不逐字清单)。
    红只给本闸广告过的那件事：**指针会漂**（序号与内容命中位置分家 / 被指那本不在盘上）。
    另两类只出声——它们的修法都要重跑付费档案（见文件头 ⑮ 那一段）。"""
    named, bare, out, stale, noquote = [], 0, [], [], []
    for book, d in sorted(books.items()):
        if src is not None and book not in src:
            continue
        for path, s in _walk(d):
            hits = list(PTR_FORM.finditer(s))
            bare += max(0, len(PTR_BARE.findall(s)) - len(hits))
            for m in hits:
                tgt, n, frag = m.group(1), int(m.group(2)), m.group(3)
                named.append((book, path, tgt, n))
                tag = _ptr_tag(book, path, tgt, n)
                if tgt not in books:
                    out.append(f"闸⑮ {tag}：被指的那本账不在盘上 ⇒ 这条指针悬空，谁都不能核它")
                    continue
                lims = books[tgt].get("limitations") or []
                if _famv(tgt)[1] < NEWEST[_famv(tgt)[0]][0]:
                    # 它指的那本已被同族新版取代。放在逐字判定**之前**算：这两件事互相独立，
                    # 若排在后面，那条引文不逐字的指针会先 continue 掉，这一桶就恒等于 0（报 0 不算测过）
                    stale.append(tag)
                pieces = [p.strip() for p in re.split(r"…|\.\.\.", frag) if p.strip()]
                moved = [i + 1 for i, x in enumerate(lims) if pieces and all(p in str(x) for p in pieces)]
                if not moved:
                    noquote.append(f"{tag}（引文『{frag}』在那本账 {len(lims)} 条里逐字命中 0 条）")
                    continue
                if n not in moved:
                    out.append(f"闸⑮ {tag}：那句引文按内容命中的是第 {moved} 条而不是第 {n} 条"
                               f"（那本账共 {len(lims)} 条）⇒ `limitations` 每升一版就在头部插一条变更说明，"
                               "写死的序号会静默漂走")
                    continue
    return named, bare, out, stale, noquote


def _ptr_toks(path):
    """`.gaps[2].note` → ['gaps', 2, 'note']：`_walk` 的路径不是字典键，读写都得先拆。"""
    toks = []
    for part in path.split(".")[1:]:
        head = part.partition("[")[0]
        if head:
            toks.append(head)
        for i in re.findall(r"\[(\d+)\]", part):
            toks.append(int(i))
    return toks


def _ptr_get(books, book, path):
    node = books[book]
    for t in _ptr_toks(path):
        node = node[t]
    return node


def _ptr_patch(books, book, path, value):
    """把 `_walk` 吐出来的路径写回 books[book]——注入腿要靠它改嵌套字段。"""
    toks = _ptr_toks(path)
    node = books[book]
    for t in toks[:-1]:
        node = node[t]
    node[toks[-1]] = value


if MODE == "--limitptr":
    import copy as _copy
    probe, _, ptr0, stale0, nq0 = _ptr_scan(arch_all, P_LATEST)
    print(f"  参评出处 = 每族最高版 {len(P_LATEST)} 本（全册 {len(arch_all)} 本）；"
          f"旧档豁免 {len(P_OLD)} 本 = {[_base(b) for b in P_OLD]}")
    if not probe:
        fails.append("闸⑮（拆红模式 --limitptr）参评那批账里没有一条可核指针可注入 ⇒ 各腿此刻全是空转，不许记成通过")
    else:
        bk, pth, tgt_book, _n = probe[0]

        def _quote_with(s, new_frag):
            return PTR_FORM.sub(lambda m: m.group(0).replace(f"『{m.group(3)}』", f"『{new_frag}』"), s)

        def _bump(s, delta):
            return PTR_FORM.sub(lambda m: m.group(0).replace(f"第 {m.group(2)} 条",
                                                             f"第 {int(m.group(2)) + delta} 条"), s)

        def _retarget(s, new_name):
            return PTR_FORM.sub(lambda m: m.group(0).replace(m.group(1), new_name), s)

        base = _copy.deepcopy(arch_all)
        orig = _ptr_get(base, bk, pth)
        frag0 = list(PTR_FORM.finditer(orig))[0].group(3)
        bad = frag0 + "（拆红注入：尾巴上多这一段，盘上没有任何账这么说）"
        # ---- 腿 E（第廿九发改道：底座不再靠盘上真缺陷）----
        # 上一版这条腿断言『全册 ≥1 条引文不逐字』，靶子就是 v4j v1 那句转述冒充引用。B 把它修成逐字之后，
        # 这条断言会**因为债被还清而红**——常驻判别器把靶子建在"现网恰好坏着"上，等于给自己安排一次报废。
        # 现在坏法由注入造，并且两向都量（0→1、再回到 0），量的是"这条计数会跟着坏法动"，不是"现网是坏的"。
        if len(nq0) or len(ptr0):
            print(f"  ⚠ 参评现读底座不是 0 / 0（不逐字 {len(nq0)}、红 {len(ptr0)}）⇒ 盘上又冒出新坏法："
                  f"注入腿照跑，但那一格先按在册缺陷读，不许顺口说『守卫全绿』")
        mut_e = _copy.deepcopy(base)
        _ptr_patch(mut_e, bk, pth, _quote_with(orig, bad))
        _, _, rE, _, nqE = _ptr_scan(mut_e, P_LATEST)
        mut_e2 = _copy.deepcopy(mut_e)                       # 反向：把引文逐字贴回去 ⇒ 桶必须降回原样
        _ptr_patch(mut_e2, bk, pth, _quote_with(_ptr_get(mut_e2, bk, pth), frag0))
        _, _, rE2, _, nqE2 = _ptr_scan(mut_e2, P_LATEST)
        print(f"  腿 E（注入）：不逐字 {len(nq0)} → {len(nqE)} → 复跑 {len(nqE2)} 条；"
              f"红 {len(ptr0)} → {len(rE)} → {len(rE2)} 条")
        if len(nqE) != len(nq0) + 1:
            fails.append(f"闸⑮（--limitptr 腿E）把引文改坏之后不逐字计数 = {len(nqE)}（要 {len(nq0)} + 1）"
                         "⇒ 『必须有原料』这条计数不承重，报 0 不算测过")
        if len(nqE2) != len(nq0) or len(rE2) != len(ptr0):
            fails.append(f"闸⑮（--limitptr 腿E 反向）把引文贴回逐字之后不逐字 = {len(nqE2)}、红 = {len(rE2)}"
                         f"（要 {len(nq0)} / {len(ptr0)}）⇒ 这条腿只会单向报警，分不清『我改坏了夹具』与『现网坏了』")
        if len(rE) != len(ptr0):
            fails.append(f"闸⑮（--limitptr 腿E）引文不逐字应当只进『不逐字』那一桶（出声不红），"
                         f"实测红 {len(rE)} 条（底座 {len(ptr0)}）⇒ 两桶混成一条，改天真要报漂移红就分不清是谁")
        # ---- 腿 D（第廿九发新增）：『过期』与『不逐字』是两桶，判定顺序不许让前一只吞掉后一只 ----
        # 第廿八发把过期判定挪到逐字判定**之前**，理由是挪在后面那一桶会结构性恒 0（报 0 不算测过）。
        # 当时没有一档会因为这件事红 ⇒ 那条修法只是我说的。这一腿就是它的凭据：先造"只过期、仍逐字"，
        # 再在它之上把引文改坏，要求两桶**同时**非零。造不出靶子就登记死闸，不许不跑就当通过。
        older = [b for b in P_OLD if _famv(b)[0] == _famv(tgt_book)[0]]
        if not older:
            print(f"  腿 D：盘上没有 {tgt_book} 的旧版 ⇒ 『指针指向旧版』这一格造不出来（**死闸**，登记不记通过）")
        else:
            tgt_old = max(older, key=lambda b: _famv(b)[1])
            lims_old = arch_all[tgt_old].get("limitations") or []
            pieces = [p.strip() for p in re.split(r"…|\.\.\.", frag0) if p.strip()]
            moved_old = [i + 1 for i, x in enumerate(lims_old) if pieces and all(p in str(x) for p in pieces)]
            if len(moved_old) != 1:
                print(f"  腿 D：那句引文在旧版 {tgt_old} 里按内容命中 {moved_old} 条（要恰好 1）"
                      f"⇒ 造不出『只过期、仍逐字』的靶子（**死闸**，不许改判据凑靶子）")
            else:
                d1_str = _bump(_retarget(orig, tgt_old), moved_old[0] - _n)   # 只改指向 + 序号按旧版算对
                mut_d1 = _copy.deepcopy(base)
                _ptr_patch(mut_d1, bk, pth, d1_str)
                _, _, rd1, sd1, nd1 = _ptr_scan(mut_d1, P_LATEST)
                mut_d2 = _copy.deepcopy(mut_d1)
                _ptr_patch(mut_d2, bk, pth, _quote_with(_ptr_get(mut_d2, bk, pth), bad))
                _, _, rd2, sd2, nd2 = _ptr_scan(mut_d2, P_LATEST)
                print(f"  腿 D：指向 {tgt_old}（那句在它那里是第 {moved_old[0]} 条）⇒ 过期 {len(stale0)} → {len(sd1)} 条、"
                      f"不逐字 {len(nq0)} → {len(nd1)} 条、红 {len(ptr0)} → {len(rd1)} 条；"
                      f"在它之上再改坏引文 ⇒ 过期 {len(sd2)} 条、不逐字 {len(nd2)} 条")
                if not (len(sd1) > len(stale0) and len(nd1) == len(nq0) and len(rd1) == len(ptr0)):
                    fails.append(f"闸⑮（--limitptr 腿D1）『只过期、仍逐字』应当只让过期那一桶动，实测 "
                                 f"过期 {len(stale0)}→{len(sd1)}、不逐字 {len(nq0)}→{len(nd1)}、红 {len(ptr0)}→{len(rd1)}"
                                 " ⇒ 这一桶与逐字判定分了家，谁漂了都说不清")
                if not (len(sd2) >= 1 and len(nd2) > len(nq0)):
                    fails.append(f"闸⑮（--limitptr 腿D2）过期 + 不逐字同时在场时读到 过期 {len(sd2)} 条、"
                                 f"不逐字 {len(nd2)} 条 ⇒ 『过期先判』把后一桶吞了（第廿八发那条修法的原病，红要报 0 就不算测过）")
        # ---- 在这个可核底座上测三条漂移腿 ----
        # 口径（第廿九发改）：断言一律写成"**相对底座的增量**"，不写绝对红数。
        # 上一版写的是"恰好 1 红 / 恰好 0 条指针"，那句话隐含的前提是"全册只有一条指针"——
        # 而 B、C 两发之后参评集合里有了**两条同形指针指同一本同一格**
        # （`v4j_matched_n8_v2` 与 `v4j_matched_n16` 的 `pays` 都指向 `v4i_mechanism_v3` 第 4 条）。
        # 于是：头部插一条会**如实地**把两条都判红（它们各自都漂了），
        #       把其中一条改成内容式会**如实地**留下另一条。绝对口径把这两件正确的事读成不承重。
        # 增量口径在只有一条指针时退化成"恰好 1"，两条时退化成"恰好 2"，都不需要再改代码。
        now = _ptr_get(base, bk, pth)
        red_tag0 = {x.partition("：")[0] for x in ptr0}
        at_tgt = [e for e in probe if e[2] == tgt_book]
        clean_at_tgt = [e for e in at_tgt if _ptr_tag(*e) not in red_tag0]
        mut_a = _copy.deepcopy(base)
        _ptr_patch(mut_a, bk, pth, _bump(now, 1))                      # 腿 A：序号 +1，内容一个字没动
        mut_b = _copy.deepcopy(base)
        mut_b[tgt_book]["limitations"].insert(                          # 腿 B：被指那本头部插一条 = 真升版的形状
            0, "（拆红注入）这一条插在最前面，模拟 limitations 每升一版在头部加一条变更说明")
        mut_c = _copy.deepcopy(base)
        # 反对照 = 把指向同一本的指针**全部**改成内容式引用（正确的修法要一次修干净；
        # 只改 probe[0] 会让"同座标那条"还留在清单里，那测的是漏改，不是正确修法）
        for e in at_tgt:
            s = _ptr_get(mut_c, e[0], e[1])
            _ptr_patch(mut_c, e[0], e[1], PTR_FORM.sub(
                lambda m: m.group(0).replace(f"第 {m.group(2)} 条", "里那句"), s))
        pa, _, ra, _, _ = _ptr_scan(mut_a, P_LATEST)
        pb, _, rb, _, _ = _ptr_scan(mut_b, P_LATEST)
        pc, _, rc, _, _ = _ptr_scan(mut_c, P_LATEST)
        want_a = len(ptr0) + 1                    # 只有被 +1 的那一条漂；同座标那条一个字没动
        want_b = len(ptr0) + len(clean_at_tgt)    # 指向同一本的那几条**全部**会漂，这是真升版的形状
        want_c = len(probe) - len(at_tgt)         # 该本的指针全改成内容式 ⇒ 从指针清单里整体消失

        def _red_with(reds, tag):
            """按身份证取那一句红，不按位置切：_ptr_scan 按账名排序，底座红与新红谁在前是盘上顺序决定的。"""
            return [x for x in reds if x.partition("：")[0] == f"闸⑮ {tag}"]

        def _cred(leg, red):
            """凭据那句红的开头必须仍是 `闸⑮`：本轮逐档红数按『以闸字开头的失败行』计数，
            把归属括号放在开头会让一条真红静默计成 0（拆红档报了 0 与没跑同形）。"""
            return f"闸⑮（--limitptr 腿{leg} 注入的凭据）{red.split('闸⑮ ', 1)[1]}"

        print(f"  底座：参评可核指针 {len(probe)} 条，其中指向 {tgt_book} 的 {len(at_tgt)} 条"
              f"（现在干净的 {len(clean_at_tgt)} 条）⇒『同一格住几条』由盘上现读决定，不写死"
              + ("；同形多条 = B/C 两发各入库一本而 `pays` 是同一句代码写的" if len(at_tgt) > 1 else ""))
        print(f"  腿 A 序号 +1：指针 {len(pa)} 条 / 红 {len(ra)} 条（要 {want_a}）；"
              f"腿 B 头部插一条：{len(pb)} 条 / 红 {len(rb)} 条（要 {want_b}）；"
              f"腿 C 改成内容式：{len(pc)} 条（要 {want_c}）/ 红 {len(rc)} 条（要 {len(ptr0)}）")
        hit_a = _red_with(ra, _ptr_tag(bk, pth, tgt_book, _n + 1))
        if len(ra) == want_a and len(hit_a) == 1:
            fails.append(_cred("A", hit_a[0]))
        else:
            fails.append(f"闸⑮（--limitptr 腿A）序号 +1 之后红 {len(ra)} 条（要 {want_a} 条，底座 {len(ptr0)} 条"
                         f"+ 被注入那 1 条）且红的身份要正好是 {_ptr_tag(bk, pth, tgt_book, _n + 1)}，实测命中 {len(hit_a)} 条"
                         "⇒ 『序号与内容分家』这条腿不承重，或者它红在了别处")
        # 腿 B 的红身份用**原序号**：这一腿改的是被指那本，指针文本一个字没动（与腿 A 相反）
        missing_b = [e for e in clean_at_tgt if f"闸⑮ {_ptr_tag(*e)}" not in {x.partition("：")[0] for x in rb}]
        cred_b = _red_with(rb, _ptr_tag(*clean_at_tgt[0])) if clean_at_tgt else []
        if len(rb) == want_b and len(set(x.partition("：")[0] for x in rb)) == len(rb) \
                and not missing_b and len(cred_b) == 1:
            fails.append(_cred("B", cred_b[0]))
        else:
            fails.append(f"闸⑮（--limitptr 腿B）被指那本头部插一条之后红 {len(rb)} 条（要 {want_b} 条，"
                         f"= 底座 {len(ptr0)} + 指向它的干净指针 {len(clean_at_tgt)} 条），"
                         f"且每条红指不同出处、点名点得到（点不到的：{[_ptr_tag(*e) for e in missing_b] or '无'}，"
                         f"凭据那一格命中 {len(cred_b)} 条）⇒ "
                         "『世界漂了而指针没跟着漂』这条腿不承重")
        if len(pc) != want_c or len(rc) != len(ptr0):
            fails.append(f"闸⑮（--limitptr 腿C 反对照）把指向 {tgt_book} 的 {len(at_tgt)} 条指针改成内容式引用之后"
                         f"仍读到 {len(pc)} 条指针（要 {want_c}）/ 红 {len(rc)} 条（要 {len(ptr0)}）"
                         "⇒ 判别器在惩罚正确的修法，会把人推回写死序号")

named_ptr, bare_ptr, ptr_red, stale_ptr, nq_ptr = _ptr_scan(arch_all, P_LATEST)
fails.extend(ptr_red)
if MODE != "--limitptr":
    if not named_ptr:
        fails.append("闸⑮ 全册一条可核指针都没读到 ⇒ 不是通过，是没测到（glob 空转，或指针换了形状而这条闸看不见）")
    else:
        print(f"  现读可核指针 {len(named_ptr)} 条（出处参评 {len(P_LATEST)} 本 = 每族最高版，"
              f"旧版豁免 {len(P_OLD)} 本）：漂走 {len(ptr_red)} 条、裸序号引用 {bare_ptr} 条；"
              f"只出声的两类 = 引文不逐字 {len(nq_ptr)} 条、过期指针 {len(stale_ptr)} 条（都不红，理由见文件头 ⑮）")
        for x in nq_ptr:
            print(f"    · 引文不逐字：{x}")
        for x in stale_ptr:
            print(f"    · 过期指针：{x}")


# ════════════════════════════════════════════════════════════════════════════
# 闸⑯ 正文引用的"库外一次性件"必须自带声明（第卅发新增·零训练）
# ════════════════════════════════════════════════════════════════════════════
# 口径（三句话，写在这条闸旁边是因为它得能被现读复算）：
#   ① 参评引用面 = 本模块**在册**的 .py/.md + 根目录那两本会引用它的文档（别的项目模块不在射程里）；
#   ② 名字**只从引用面正文里现读**：凡用反引号写成**整名**、且形状是"能落到盘上的路径"——以已知
#      扩展名结尾（`_CIT_EXT` 那张表：.log/.py/.json/.md/.pt/.onnx/…）或以 `/` 结尾的目录写法——
#      而它**不是任何全仓在册路径的尾段**、也不是任何在册路径的目录前缀 ⇒ 判为断链指针；每一次提到
#      它，±2 行内必须有一行**同时含这个名字和一个声明词**（点名式声明）。
#      形状这一条是第卅一发现读补的：第卅发那句"下划线开头或以 .log 结尾"太宽，直接套会把 447 处
#      `_n8`/`_v4`/`_ptr_tag` 这类**尾段简写**和别的模块的在册件（`ask.py`）读成断链——实测 56 处假红。
#   ③ 点不到名 ⇒ 红。判的是"clone 之后这句话还成不成立"，不是"此刻这台机器上有没有那个文件"。
# 为什么要一条闸而不是又一轮人肉搬：同一件事三发里坏了三次——第廿八发记下、第廿九发结掉一半的
# 新欠⑶（本文件里那三处 _tmp_redNN 日志）、本轮菜单 B 搬掉的三处、**装这条闸时现读又抓到的一处**
# （第廿二发那条"第一次跑 8 条流被杀"的墙钟原件）。每一次写的人都是诚实的：他当时看得见那个文件。
# 会说谎的是"盘上"这两个字，不是人——所以这条闸管的是措辞欠下的义务，不是文件的存在。
# 〔第卅一发收紧两处，都是先量后改〕
# 一、名字来源从「盘上现读 ∪ 手写登记处 SCRATCH_CITED」换成**纯正文现读**。原先那句"只扫盘 ⇒
#     清理之后裸引用永远查不红"站不住：裸引用里那个名字本来就是正文给的，`os.listdir` 那一半从来
#     不是必要条件，它只让**分母跟着这台机器的目录漂**（第卅发同一轮两次裸跑之间名字数 100→108）。
#     登记处那一半则是第卅发明记的新欠——下一发新造的名字没人补它。两个来源换成一个来源，
#     漂移和衰减**同时**结掉。如实记下丢掉的那一半覆盖：不带反引号写出来的名字不在射程里，
#     这条闸认的是"反引号整名"这个书写约定，不是"一切指向库外的措辞"。
# 二、声明判定从「±2 行内出现标记词」收紧成「±2 行内有一行同时含**这个名字**和标记词」（点名式）。
#     旧口径留着一个自我消音的口子：正文里任何一句写了"本机/库外/清理清单"的话——哪怕说的是别的
#     文件——都会替旁边那条真断链作保。收紧前先在盘上量了三种口径（`_tmp_r31_legprobe.py`，一次性件）：
#     ±2 行 55 带声明 / 0 裸；同行 46 / 9；点名式 46 / 9，且**后两档判红的集合完全相同**（两个差集都
#     是空）⇒ 那 9 处不是假红，是措辞确实没点名的债。**但"9"是收紧前那一次测量的数，不能拿来当整改
#     清单**：形状判据（上一条②）落地之后，同一句正文现读出的裸引用是 **24 处**，那 9 处只是它的子集。
# 三、24 处的处置与"收益"（第卅一发菜单 B：24 处**全部改正文**，另外给声明词表加了两个词，加完当场量了它承重多少）：
#        词表从 HEAD 版的十个词加到十二个（新增 `不入库|已删除`）。加词不是免费的，所以收口时跑了
#        一次两遍对照（把 `_LOCAL_MARK` 临时换回 HEAD 版、原样重跑 `normal`、再逐字节还原）：
#        **HEAD 词表下 ⑯ 报 14 条裸引用，现词表下 0 条** ⇒ 那两词替 14 处作了保，是承重的。
#        那 14 处逐条抄出来核过：每一句都写着"不入库""此件不入库""账已删除""验完即删、不入库"
#        这一类真声明（`_tmp_r31_markdiff.txt`，本机、不入库）⇒ 判读是**词表认不出同义词**（旧表有
#        `不在库里`/`库外` 却没有 `不入库`），不是把假话说绿。但这条账必须登记：**加词让 14 处变绿，
#        而守卫里没有任何一档会因"词表被加宽"而红**——第卅发新欠⑸ 预言的正是这个失效模式，本轮
#        由我自己兑现了一次。
#     ① 措辞没点名 → 把声明写成点名的（`summary.txt` 与 `_qq.py` 都是本机一次性件、已删除，
#        `step4l` 那两本改名件不入库，`data/fashion/` 那一行改成点名"不在库里"）；
#        ② **实质假话** → 六处把 `models/*.pt` 写成"已入库/在盘"，现读
#        `git ls-files` 全仓在册 `.pt` = **0 本**、`models/` 是 `ml-compress/.gitignore` 第一行，那六个
#        字是假的，不是欠一个标记词 ⇒ 改成本机 + 不入库 + 可复现命令（`train_baseline.py` /
#        `step5_second_teacher.py --teacher B|C` / `step6_fashion_replication.py`）；那种"绿"若靠加
#        词表换来，闸就等于被整改对象改写了。整改后 normal rc=0 / 0 红。
#     ③ **本闸的已知盲区，由腿G 量着而不是靠这句话自认**：点名式只要求"名字与声明词**同现于一行**"，
#        管不了那个词是不是在说这个名字——README:1158 就是活例（那行的"本机"修饰的是"同期本机有 21 个
#        并存的 python 进程"，跟那本日志无关，却让这句引用合法变绿）。腿G 注入的就是这个形状，
#        期望 0 红（盲区成立）；哪天判据严到能红了，腿G 会反过来红着要求把这段话改写。
# 词表哨兵（第卅二发·结第卅一发新欠⑵）：一句**真声明**用的词，但它**不在**上面那张表里。
# 为什么需要它：上一发整改 24 处裸引用时我给词表加了两个词，加完量出"那两个词替 14 处作了保"——
# 可是**守卫里没有任何一档会因为『词表被加宽』而红**，也就是说下一次加词可以悄无声息地发生。
# 这条哨兵把"加词"变成一件必须留痕的事：把它收进词表 ⇒ 下面那条常驻红立刻点名（在 normal 与每一档都跑）。
# 想加词的人必须同时改这个常量，而那在 diff 里是一行藏不住的话——就像腿E 之于"换行位置承重"。
_SENTINEL_MARK = "用完即删"
_LOCAL_MARK = re.compile(r"本机|不在库里|库外|不入库|已删除|gitignore|断链|作废|叙述级|清理清单|一次性件|永久保留")
_nmark16 = len(_LOCAL_MARK.pattern.split("|"))   # 词数现读：加词/删词都会改这个数，文案不写死
# 句界（第卅八发 E）：只认句终符 。！？ 与半／全角分号。**逗号、冒号、顿号故意不算**——算了就把
# "同段写明"变成"紧邻声明"，同一句里的补语也会被切开（第卅八发量过：软句口径把 9 处抬到 51 处）。
_SENT_BREAK = re.compile("[。！？;；]")
# 登记处（第卅九发 C·还第卅八发新欠⑶）：上面那张表**应当**含哪些字符，单独写一行。
# 它不新增判据，只把"改表"变成一件必须同时改两行的事——只动表不动这里 ⇒ 下面那条常驻红点名。
# 限度也说清：两行一起改、且正文那批"名字与声明分居两句"的引用恰好不受影响时，这一型只能靠
# diff 留痕（同第卅二发词表哨兵的强度，不吹成更多）。逐字符各自承重由 `--sentbreak` 现读。
_SENT_BREAK_EXPECTED = "。！？;；"
# 下限票（第四十发 E·还第卅九发新欠那一型"两行一起改"）：登记处与表是一对"必须一起改"的两行，
# 所以**把两行一起摘掉一个字符**时上面那条对账照旧绿——第卅九发把这型登记成"只能靠 diff 留痕"。
# 这一票不比登记处，比**历史下界**：这几个字符各自被 `--sentbreak` 量出过承重（移出表⇒正文那处静默变绿），
# 所以从表里摘掉其中任何一个都是把判据变松，而"变松"不该是"多改一行"就能自我批准的。
_SENT_BREAK_FLOOR = "。！？;；"
_SENT_CLASS = re.fullmatch(r"\[(.*)\]", _SENT_BREAK.pattern)
_SENT_CHARS = sorted(set(_SENT_CLASS.group(1))) if _SENT_CLASS else None


def _sent_table_votes(table, expected, floor):
    """句边界表的两票，做成纯函数：登记处对账（表 == 登记处 才绿）＋历史下限票（floor ⊆ 表 才绿）。
    第四十发 E：normal 用真实三值跑一遍，`--sentfloor` 用"表与登记处一起摘一个字符"的值再跑一遍，
    要的就是**旧票绿而新票红**——旧票绿是这一型的反面凭据（它测不到一起改），新票红是这条票的牙。"""
    _t = sorted(set(table or []))
    return sorted(set(expected)) != _t, [c for c in sorted(set(floor)) if c not in _t]


# 下限的来源（第四十一发 C·还第四十发新欠⑺）：`_SENT_BREAK_FLOOR` 的内容是我写的一行字，而旧的两条票
# （登记处对账、下限 ⊆ 表）**都不比它和盘上历史的关系** ⇒ 把这一行自己摘短，两条旧票双双读不到。
# 这一票的尺子不住在这几行里：它从 `git show HEAD:` 那一份文件里现读那张表，所以"摘短下界行"必须改
# 工作树而改不动 HEAD ⇒ 当场红。
_SENT_HEAD_LINE = re.compile(r'^_SENT_BREAK = re\.compile\((?:r)?"\[(.*?)\]"', re.M)


def _sent_table_from_head():
    """HEAD 里那张句边界表的字符集。返回 `(True, 排序后的字符列表)` 或 `(False, 为什么读不到)`。
    三态口径照旧：读不到必须报成**无从开口**，不许当成空集合——当成空集合就等于把"摘短下界行永远绿"
    换了一种写法（第 118 条：下限不许由被检对象的表自己算，这里连"自己"都不给了）。"""
    _rel = os.path.basename(os.path.abspath(__file__))
    _path = _MOD_PREFIX + "/" + _rel if _MOD_PREFIX else _rel
    _res = subprocess.run(["git", "-c", "core.quotepath=false", "show", "HEAD:" + _path],
                          capture_output=True, text=True, encoding="utf-8", errors="replace")
    if _res.returncode != 0:
        return False, ("`git show HEAD:" + _path + "` 退码 " + str(_res.returncode) + "（"
                       + ((_res.stderr or "").strip()[:70] or "无 stderr") + "）")
    _m = _SENT_HEAD_LINE.search(_res.stdout)
    if not _m:
        return False, ("HEAD 那份文件里没找到形如「_SENT_BREAK = re.compile(引号加方括号)」的纯字符类那一行"
                       "（形状被改写过 ⇒ 是尺子瞎了，不是判据变松了）")
    return True, sorted(set(_m.group(1)))


def _sent_votes4(table, expected, floor, head):
    """三票一起算，给常驻对账和 `--floorcut` 的注入用同一把口径：
    ① 登记处对账（表 == 登记处）、② 历史下限票（下界 ⊆ 表）、③ 下限来源票（HEAD 那张表 ⊆ 下界）。
    ③ 是第四十一发 C 新加的那一票：它不比"几行之间是否一致"，比"这一行有没有比盘上历史短"，
    所以『只摘下界行』和『表／登记处／下界三行一起摘』这两型它读得到而 ①② 读不到。"""
    _eq_red, _missing = _sent_table_votes(table, expected, floor)
    _fl = sorted(set(floor))
    _src = [c for c in sorted(set(head)) if c not in _fl]
    return _eq_red, _missing, _src


_BT_TOKEN = re.compile(r"`([^`\s]{3,})`")
_ROOT_DOCS = ("../README.md", "../项目复盘与简历写法.md")


def _git_tracked(extra=(), use_dot=True):
    """在册名单。cwd 恒为本模块目录，所以模块内是相对名、根目录那两本带 ../。
    `.` 是承重的：少了它，git 把 pathspec 当**过滤**用 ⇒ 名单塌成那两本，本模块所有在册件
    （含 `_red_v3.py` 自己、`_coef_check.py`）都会被误判成"库外断链"。第卅发就是这么坏的。"""
    return [x for x in subprocess.run(
        ["git", "-c", "core.quotepath=false", "ls-files"] + (["."] if use_dot else []) + list(extra),
        capture_output=True, text=True, encoding="utf-8").stdout.splitlines() if x]


def _git_repo_paths():
    """**全仓**在册路径，且按仓库根写。两个坑都是第卅一发现读抓到的：
      ① pathspec 必须写 `:/`——`git ls-files` 不带参数只列当前子目录（本目录实测 145 本 vs 全仓 326 本），
         拿它当分母会把别的模块的在册件（`ask.py`、`scripts/cloud_probe.py`）读成库外断链；
      ② 必须加 `--full-name`——不带它时 `:/` 返回的是相对 cwd 的 ../ml-compress/README.md 那种形态，
         而正文按仓库根写 `ml-compress/README.md`，尾段判据对不上 ⇒ 在册件照样被点名。"""
    return [x for x in subprocess.run(
        ["git", "-c", "core.quotepath=false", "ls-files", "--full-name", ":/"],
        capture_output=True, text=True, encoding="utf-8").stdout.splitlines() if x]


CIT_TRACKED = _git_tracked(_ROOT_DOCS)
CIT_NAMES = {p.rsplit("/", 1)[-1] for p in CIT_TRACKED}
CIT_REPO = _git_repo_paths()

_CIT_EXT = re.compile(r"\.(?:log|py|json|md|txt|pt|pth|onnx|csv|tsv|html|bat|sh|yml|yaml|ini|lock|xml)$")
_DOTDOT = re.compile(r"(?:^|/)\.\.(?:/|$)|^\./")


def _repo_prefix():
    """本模块在**仓根**下的目录名，由 git 现读（`rev-parse --show-prefix` 回 `ml-compress/`）。
    写死它等于赌这个目录永远叫这个名字，而反解相对引用全靠前缀。"""
    return subprocess.run(["git", "rev-parse", "--show-prefix"],
                          capture_output=True, text=True, encoding="utf-8").stdout.strip().rstrip("/")


_MOD_PREFIX = _repo_prefix()


def _ref_dir(path):
    """引用者所在目录（仓根相对）。cwd 在本模块，所以模块内的 `README.md` 在仓根看是
    `ml-compress/README.md`；根目录那两本本来就带上一级前缀，去掉便是仓根。
    合成夹具的键（`__注入A__`）走模块那一支 ⇒ 它的反解口径与真模块文件一致。"""
    rel = path[3:] if path.startswith("../") else posixpath.join(_MOD_PREFIX, path)
    return posixpath.dirname(rel)


def _resolve_ref(tok, ref_dir):
    """把带目录前缀的写法反解成仓根相对的键。回 None 的三种情形就是"不放宽"的三条：
      ① 写法里没有 `..`/`.` 段 ⇒ 归一不插手（那种写法本来由旧判据的尾段规则处理）；
      ② 反解后爬出仓根 ⇒ `../` 的层数超过引用者所在深度，语义上就是库外，夹紧它等于把库外读成在册；
      ③ 反解后落在 `.` 或空串 ⇒ 那是"整个仓根"而不是某个原件，拿它比在册名单会把裸 `../`
         洗白成命中 `.gitignore` 那一类（第卅九发现读到这一型真在正文里，见 `--dotdot` 腿C）。"""
    if ref_dir is None or not _DOTDOT.search(tok):
        return None
    joined = posixpath.normpath(posixpath.join(ref_dir + "/", tok))
    if joined.startswith("..") or joined in (".", ""):
        return None
    return joined


def _registry_hit(tok, repo_paths, ref_dir=None, resolve_prefix=True):
    """在册命中只有两条路，**先后有序**：尾段命中（第卅一发起的旧判据，一字未动）优先；
    它落空之后才允许按引用者目录反解（第卅九发 E 补的归一，只对带前缀的写法开）。
    顺序反了就会让归一去覆盖旧判据——那是放宽，不是补洞。"""
    if any(p.endswith(tok) for p in repo_paths):
        return True
    if not resolve_prefix:
        return False
    r = _resolve_ref(tok, ref_dir)
    if r is None:
        return False
    if tok.endswith("/"):
        return any(p.startswith(r + "/") for p in repo_paths)
    return any(p == r for p in repo_paths)


def _scratch_pointer(tok, repo_paths, ref_dir=None, resolve_prefix=True):
    """这个反引号整名是不是一次性件的指针。四条都过才算：
      ① 不是 glob／省略写法（`compress_report_v4f*.json`、`..._n8_v4.json` 指向的是账族，不是某个原件）；
      ② 形状是**完整**件名：以已知扩展名结尾，或以 `/` 结尾；这条挡掉 447 处 `_n8`/`_v4`/`_ptr_tag`
         那类尾段简写与标识符（它们不是路径）；
      ③ 不是任何全仓在册路径的**尾段**：一处判据同时挡掉在册件本身（`_red_v3.py`）、它的相对写法
         （`scripts/cloud_probe.py`）和在册账名的尾段（`_fashion.json` 是
         `compress_report_v6_fashion.json` 的尾巴）；
      ④ 目录写法（`ml-compress/`）若命中任何在册路径的**目录前缀** ⇒ clone 之后那个目录在，不算断链；
         落空的留在射程里——比如 `data/fashion/`（本机一次性件、运行时下载的数据集目录）。
    第卅九发 E 补的第⑤条**只在上面四条落空时才参与**：带 `../`/`./` 前缀的写法按引用者所在目录反解
    （`_registry_hit`），所以"在册件的前缀写法"从这一发起不再靠一句声明才绿——反解不出在册原件的
    照旧算断链，归一不替真断链洗白。"""
    if "*" in tok or "?" in tok or tok.startswith("..."):
        return False
    if _CIT_EXT.search(tok):
        return not _registry_hit(tok, repo_paths, ref_dir, resolve_prefix)
    if tok.endswith("/"):
        seg = tok.rstrip("/")
        if any(p.startswith(seg + "/") or ("/" + seg + "/") in p or p.endswith("/" + seg + "/")
               for p in repo_paths):
            return False
        return not _registry_hit(tok, repo_paths, ref_dir, resolve_prefix)
    return False


def cited_surfaces(tracked=None):
    """引用面只收**在册**文件：草稿引草稿不是断链（第廿九发 F 清点踩过的第二个坑）。"""
    tracked = CIT_TRACKED if tracked is None else tracked
    cands = sorted(glob.glob("*.py") + glob.glob("*.md")) + list(_ROOT_DOCS)
    return {p: open(p, encoding="utf-8").read().splitlines()
            for p in cands if p in tracked and os.path.isfile(p)}


def cited_denominator_ok(tracked):
    """分母自证：在册名单必须收得下本模块自己（`_red_v3.py` 在册且以 `_` 开头，是最省事的探针）。
    名单一旦塌成引用面那两本，这条闸会把满目录的在册件当断链点名——那种红看着像正文的债，其实是分母坏了。"""
    return "_red_v3.py" in {p.rsplit("/", 1)[-1] for p in tracked} and len(tracked) > 20


def cited_universe(surfaces, repo_paths=None, resolve_prefix=True):
    """(每个库外一次性件指针 → 它被提到的地方, 指针种类数)。
    名字只有这一个来源：正文里的反引号整名。不扫盘、不靠手写登记处——第卅一发起这是口径的一部分。
    `resolve_prefix=False` 把第卅九发 E 的归一关掉（旧判据单独扫一遍），常驻那行两向对账和
    `--dotdot` 腿就是拿它做"同一把尺子的两个来源"，不是拿上一发的日志当基线。"""
    repo_paths = CIT_REPO if repo_paths is None else repo_paths
    hits = {}
    for path, ls in surfaces.items():
        d = _ref_dir(path)
        for i, line in enumerate(ls, 1):
            for m in _BT_TOKEN.finditer(line):
                tok = m.group(1)
                if _scratch_pointer(tok, repo_paths, d, resolve_prefix):
                    hits.setdefault(tok, []).append((path, i))
    return hits, len(hits)


def _sent_span(joined, off):
    """偏移 `off` 落在哪一句里，连同**该句在 joined 里的起点**一起回（反方向腿要按句内偏移
    判『引用 vs 使用』，只回文本就丢了坐标）。"""
    pos = 0
    for s in _SENT_BREAK.split(joined):
        if pos <= off < pos + len(s):
            return s, pos
        pos += len(s) + 1
    return "", 0


def _sent_of(joined, off):
    """偏移 `off` 落在哪一句里（句界只认 。！？ 与半／全角分号；逗号冒号不算，
    否则判据就从『同段』滑成『紧邻』——第卅八发 E 量过那一档：软句会把 9 处抬成 51 处）。"""
    return _sent_span(joined, off)[0]


def _cited_pass(surfaces, hits, strip_win, unit):
    """两遍判定的**同一个**循环，只有"救回"的单位不同：
      unit=`row`      甲＝第卅一发起的旧单位，窗口里有一整**物理行**同时含名字与声明词；
      unit=`sentence` 戊＝第卅八发 E 采用的单位，窗口仍以 ±2 行为**段**（行与行以空格相接，
                      所以跨行的一句不会被行尾切开），但点名与声明必须落在**同一句**里。
    为什么整行不够：引用面的**物理行**长度由闸⑯ 后面那条常驻读数现读（第卅八发 E 量到时中位 180、
    p90 5330、最长 32007 字符）——README 的『一整发写进行』落地段就属于后者，在那种行上
    『同一物理行』＝『同一文档』，整行单位等于没判。"""
    bare, saved = [], []
    for nm, where in hits.items():
        for path, ln in where:
            if path not in surfaces:
                continue
            lines = list(surfaces[path])
            lo, hi = max(0, ln - 3), min(len(lines), ln + 2)
            if strip_win == (path, ln):
                for j in range(lo, hi):
                    lines[j] = _LOCAL_MARK.sub("", lines[j])
            if unit == "row":
                ok = any(nm in x and _LOCAL_MARK.search(x) for x in lines[lo:hi])
            else:
                line = lines[ln - 1] if ln - 1 < len(lines) else ""
                joined = " ".join(lines[lo:hi])
                base = sum(len(lines[j]) + 1 for j in range(lo, ln - 1))
                ok = any(_LOCAL_MARK.search(_sent_of(joined, base + m.start()))
                         for m in re.finditer(re.escape(nm), line))
            (saved if ok else bare).append((nm, path, ln))
    return sorted(bare), sorted(saved)


def cited_scan(surfaces, hits, strip_win=None):
    """返回 (裸引用, 被声明救回)。判定＝点名式**且段内同句**（戊）：±2 行的段里，
    含这个名字的那一句必须同时含一个声明词。旧口径（整行）只要那一行里名字与声明词共现就放行
    ⇒ 正文里任何一句"本机/库外/清理清单"——哪怕它说的是别的文件、哪怕它在七千字符之外——
    都会替旁边那条真断链作保（自我消音）。strip_win=(文件, 行号) 只改内存里那一处的窗口。"""
    return _cited_pass(surfaces, hits, strip_win, "sentence")


def cited_scan_row(surfaces, hits, strip_win=None):
    """甲（整行单位）的同一遍扫描。**不作判据**，只用来现读"把判定单位从行收到句"这一步
    到底改变了多少处——那个差额就是本轮还的债的面，也是 `--longline` 的专属校验目标。"""
    return _cited_pass(surfaces, hits, strip_win, "row")


# 反方向腿（第四十二发 B）。词面比 `_LOCAL_MARK`（12 词，旧判据拿来"救回"裸引用）**窄**：
# 旧判据的声明词讲的是"这东西是临时/废弃/一次性"，而这一腿要抓的是"这东西**不在库里**"这一句假话。
# 把 12 词直接搬过来会红一大批合法的"这本是旧账"式表述，那是把判据换成噪声。
_OUTSIDE_CLAIM = re.compile(r"不在库里|库外|不入库|未入库|没入库|不在册|gitignore|已删除")


def _inrepo_whole_name(tok, repo_paths, ref_dir=None):
    """反方向腿的在册判据：只认**整名**。为什么不能直接复用旧判据的 `_registry_hit`：
    它的头一条是 `p.endswith(tok)`（尾段命中），那条规则是为"名字落空才开口"的旧判据省的
    （宽一点只会少报断链），但这一腿反过来用就变成假警发生器 ⇒ 正文里 `.py`／`.md` 这种**片段写法**
    （首实测：`README.md:1621` 那句『`.py`／`.md`（本机、不入库）』本来就在做声明）和
    `_fashion.json` 这种尾段简写都会被当成"一个在册原件被说成库外"。整名 = 等于某个在册路径，
    或以 `/整名` 结尾；带 ../ 前缀的写法仍按引用者目录反解后要求**逐字相等**。"""
    bare = tok.rstrip("/")
    if tok.endswith("/") and any(p.startswith(tok) or p.startswith(bare + "/") for p in repo_paths):
        return True
    if any(p == tok or p.endswith("/" + tok) for p in repo_paths):
        return True
    r = _resolve_ref(tok, ref_dir)
    return r is not None and any(p == r for p in repo_paths)


_QUOTE_PAIRS = (("『", "』"), ("「", "」"), ("“", "”"), ("\"", "\""), ("'", "'"), ("`", "`"))


def _quote_spans(text):
    """`text` 里被引号括住的区间（同一种引号按出现次序两两配对；句子可能被句界从一对引号中间
    切开，落单的半边自然配不上，就不算『被提及』⇒ 宁可让裸露的那一半继续开口）。"""
    spans = []
    for open_, close_ in _QUOTE_PAIRS:
        start = None
        for i, ch in enumerate(text):
            if ch == open_ and start is None:
                start = i
            elif ch == close_ and start is not None:
                spans.append((start, i + 1))
                start = None
    return spans


_FC_MAX_GAP = 24
_STRIKE = re.compile(r"~~.*?~~")                       # 划掉的句子＝板块"原文照抄不删"留下的记录
_RETRACT = re.compile(r"〔[^〕]*更正[^〕]*〕")          # 就地贴的那种方括号更正
_FC_CLOSE = re.compile(r"[）)〕』」》】]")              # 闭括号：出现了就说明那一栏已经合上
_FC_PRENOM = re.compile(r"[的、，, \t]*")               # 声明词与后一个名字之间只许隔助词


def _retracted_word(seg, word):
    """同段里有没有一个 `〔…更正…〕` 把 `word` 用引号点了名。为什么要看到**段**而不是句子：
    板块就地贴更正的写法是『…那句假声明。〔第四十一发现读更正：这句"不入库"是当时的事实，
    已经买掉了〕』——更正括号住在**下一句**，只看含名字那一句就永远读不到它。
    要求"引号点名"而不是"段里有个更正括号"，是为了不把作保的面放开：只在括号里逐字出现
    `『X』`／`"X"`／`“X”` 这一型才算这句话正在作废这个声明。"""
    for body in (m.group(0) for m in _RETRACT.finditer(seg)):
        for open_, close_ in _QUOTE_PAIRS:
            if open_ == "`":
                continue
            if open_ + word + close_ in body:
                return True
    return False


def _claim_of(mark, sent, name_end, seg=None):
    """名字**之后** `_FC_MAX_GAP` 个字符以内、第一个被**使用**（不在引号里）的库外声明词。
    为什么要带上位置：首实测（整名＋提及两条收紧之后）仍剩 65 处／46 行，逐行读下来绝大多数是
    "同一句里那个库外词说的是**别的**对象"——例如 README 里那句『`*.log` 被本目录 `.gitignore`
    挡在库外 ⇒ 盘上可核的那一份改成已入库的那份守卫源码文件头那张表』，在册名字与那个词共处一句，
    而那句从头到尾没替这份守卫源码说过任何一句话。第四十一发㈥那四处真声明的共同形状是
    『`X` 那本不在库里』『`X`〔这本还没入库〕』⇒ **声明紧跟名字**。名字之前的库外词一概不看，
    这是这一腿的**限度**（写在句子里先否定、再点名的写法会漏），`--falseclaim` 的注入用的就是
    紧跟那一型，所以它的反面凭据只证"紧跟型有牙"，不证"前置型也拦得住"。
    第二、三次实测（65 → 18 处）把剩下的形状读完，又添两条**声明不归这个名字**的筛除：
      ④ 撤正记录：声明词被 `~~…~~` 划掉，或同句里有 `〔…更正…〕` 那种方括号更正 ⇒ 这句话正在**作废**
         那个声明，不是重复它。不加这一条就等于要求作者把历史原文改掉，与板块"原文照抄不删＋就地贴更正"
         的规矩对着干；首实测里 5 处属于这一型（`README.md:1268`／`:1858`、`项目复盘:203`、
         `_red_v3.py:473`／`:679`，全是『被 gitignore 挡着、不在库里』那两句已作废的话）。
      ⑤ 错挂：名字与声明词之间出现闭括号 ⇒ 名字所在那一栏已经合上，声明归栏外（`README.md:1353`
         的『…`_tmp_vdiff.py`）／**被正文引用而未入库 12 件**』），或声明词与**后**一个反引号名字之间
         只隔助词 ⇒ 那个词是给后面那个名字用的（`README.md:247` 的『…追加进 gitignore 的
         `latency_history_v3.json`』——被点名的那支剪枝脚本本身在册，而那本机器本地历史文件才真在库外）。
    两条的代价写在常驻打印里：④ 的同句那一支**只要同句里有一个 `〔…更正…〕`，它就能替旁边一句真没作废的
    假声明作保**；同段那一支收得窄一些（括号里必须逐字用引号点出**这个词**），代价是"先作声明、
    隔一句再更正"这种写法因此永远绿——而板块"原文照抄不删＋就地贴更正"的规矩本来就长成这个样子。"""
    seg = sent if seg is None else seg
    spans = _quote_spans(sent)
    strikes = [(m.start(), m.end()) for m in _STRIKE.finditer(sent)]
    retracted = bool(_RETRACT.search(sent))
    names = list(_BT_TOKEN.finditer(sent))
    for m in mark.finditer(sent):
        if m.start() < name_end or m.start() - name_end > _FC_MAX_GAP:
            continue
        if any(st <= m.start() < en for st, en in spans):
            continue
        if retracted or any(st <= m.start() < en for st, en in strikes):
            continue                       # ④ 撤正记录：这句话正在作废那个声明
        if _retracted_word(seg, m.group(0)):
            continue                       # ④ 同段的更正括号用引号点名了**这个词**
        if _FC_CLOSE.search(sent[name_end:m.start()]):
            continue                       # ⑤ 闭括号 ⇒ 那一栏已经合上
        nxt = [n for n in names if n.start() >= m.end()]
        if nxt and _FC_PRENOM.fullmatch(sent[m.end():nxt[0].start()]):
            continue                       # ⑤ 那个词是后面那个名字的定语
        return m
    return None


def cited_inrepo_claims(surfaces, repo_paths=None, mark=_OUTSIDE_CLAIM):
    """闸⑯ 旧判据的**反方向**：正文引的名字**在册**，而紧跟名字那一句里写着"它不在库里"那一类声明
    ⇒ 声明本身是假的，红。为什么旧判据看不到这一型：它只在"名字不在册"时才开口，
    所以把在册件说成库外不会让任何一档变红——第四十一发㈥那四处『被 gitignore 挡着』的假声明
    是四桶清点时人肉读出来的，守卫当时整套 38 份里没有一条点名它。
    句的单位与旧判据**同一把**（±2 行的段里、由 `_SENT_BREAK` 切出的那一句），两条腿共用
    `_sent_span` ⇒ 不再长出第二把尺子；但**射程比旧判据窄五条**，每一条都是实测读出来的（80 → 65 → 18 处）：
      ① 名字要整名命中在册路径（`_inrepo_whole_name`，尾段简写 `.py`／`_fashion.json` 不算）；
      ② 声明词要处于"使用"而非"提及"（被引号括住的那些是在谈这个词本身）；
      ③ 声明词要**紧跟**名字（`_claim_of`，`_FC_MAX_GAP` 字符以内）——同句不同对象那一型占首实测
         的红面绝大多数，不收到这里，这一腿就是把判据换成了噪声；
      ④ 撤正记录不算活体：声明词被 `~~…~~` 划掉、同句里有 `〔…更正…〕`，**或**同段的更正括号里用引号
         逐字点出了这个声明词（`〔…这句"不入库"是当时的事实，已经买掉了〕` 这一型——更正通常贴在下一句，
         只看含名字那一句读不到它）⇒ 那句话正在作废这个声明
         （板块规矩是"原文照抄不删＋就地贴更正"，判这一型红等于要求作者改历史原文）；
      ⑤ 错挂不算：名字与声明词之间出现闭括号（那一栏已经合上），或声明词与后一个反引号名字之间只隔助词
         （那个词是后面那个名字的定语）。
    ④⑤ 的代价明写在常驻打印里：**同句那一支里一个 `〔…更正…〕` 能替旁边一句真没作废的假声明作保**，
    而"先作声明、隔一句再拿引号点名同一个词"这种写法结构性地永远绿（③ 另有一支前置型不在射程）。
    反面凭据在 `--falseclaim`：合成注入面里那一处必须被点名，而"只提名字、不作库外声明"必须**不**红
    （否则这一腿恒红，正文只能靠改口过闸）。"""
    repo_paths = CIT_REPO if repo_paths is None else repo_paths
    out = []
    for path, lines in surfaces.items():
        rd = _ref_dir(path)
        for ln, text in enumerate(lines, start=1):
            lo, hi = max(0, ln - 3), min(len(lines), ln + 2)
            joined = " ".join(lines[lo:hi])
            base = sum(len(lines[j]) + 1 for j in range(lo, ln - 1))
            for m in _BT_TOKEN.finditer(text):
                tok = m.group(1)
                if "*" in tok or "?" in tok or tok.startswith("..."):
                    continue
                if not (_CIT_EXT.search(tok) or tok.endswith("/")):
                    continue
                if not _inrepo_whole_name(tok, repo_paths, rd):
                    continue                         # 不在册的归旧判据，这一腿只看在册的
                sent, sent_off = _sent_span(joined, base + m.start())
                # 名字结尾＝`m.end()` 已经指在闭合反引号的下一格（joined 里该行的起点就是 base）
                _w = _claim_of(mark, sent, base + m.end() - sent_off, joined)
                if _w:
                    out.append((tok, path, ln, _w.group(0)))
    return sorted(out)


def _c16_own_red(f):
    """闸⑯ 各拆红档在收尾时都要清一遍"有没有红走漏到别的判据"，那份清点必须先摘掉**正文自己的**红：
    旧方向的断链引用红、第四十二发 B 新加的反方向假声明红。两者都不是注入产生的，
    把它们读成"注入串味"就是第卅四发 E 那一型（把盘面已有的红当成注入的证据）。"""
    return f.startswith("闸⑯（断链引用）") or f.startswith("闸⑯（在册件被说成库外）")


